def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'
    if n == 1:
        return 'D' if history[0][1] == 'D' else 'C'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    last_me = me[-1]
    last_opp = opp[-1]

    opp_c = 0
    my_c = 0
    for m, o in zip(me, opp):
        if m == 'C':
            my_c += 1
        if o == 'C':
            opp_c += 1

    opp_d = n - opp_c
    my_d = n - my_c

    od_streak = 0
    for o in reversed(opp):
        if o == 'D':
            od_streak += 1
        else:
            break

    before_len = n - od_streak
    own_c_in_streak = 0
    for m in me[before_len:]:
        if m == 'C':
            own_c_in_streak += 1

    before_c = 0
    for o in opp[:before_len]:
        if o == 'C':
            before_c += 1

    recent3 = opp[-3:] if n >= 3 else opp
    recent3_d = sum(1 for o in recent3 if o == 'D')
    recent10 = opp[-10:] if n >= 10 else opp
    recent10_c = sum(1 for o in recent10 if o == 'C')

    if opp_d == 0:
        if n >= 90 or (n >= 30 and rng.random() < 0.02):
            return 'D'
        if last_me == 'D':
            return 'D'
        return 'C'

    if last_opp == 'D':
        if last_me == 'C' and history[-2][0] == 'D' and history[-2][1] == 'D':
            return 'C'

        if od_streak == 1 and recent10_c >= 9 and opp_d <= 2:
            if rng.random() < 0.35:
                return 'C'

        if od_streak >= 4 and opp_c > opp_d and before_c >= 6 and own_c_in_streak < 3:
            if last_me == 'D':
                return 'C'

        return 'D'

    if last_opp == 'C':
        if opp_d > opp_c and recent3_d >= 2:
            return 'D'
        if opp_d > opp_c + 6:
            return 'D'

        if last_me == 'D' and opp_c > opp_d and opp_d <= max(2, n // 8):
            if rng.random() < 0.2:
                return 'D'

        return 'C'
